/**
 * The published key reader page is exactly what its sources build to, and nothing else.
 *
 * `reference/key-reader/` is generated by `bin/build.ts`, the way `reference/silhouettes/` is generated by
 * its package, and the website copies the folder as it is. So a hand edit to a published file, a source
 * changed without `make key-reader`, or a stray file in the folder would put something on the site that no
 * source states and no test of `src/` has seen. Every other test of this package reads the published files,
 * and this one is what makes that the same as reading the sources.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { buildKeyReader, driftFrom } from '../bin/build.ts';

test('reference/key-reader/ holds exactly what the build makes', () => {
  assert.deepEqual(driftFrom(buildKeyReader()), []);
});

test('the page is the entry, its link, press reading, modes and face, the drawings, and the three library modules that import nothing', () => {
  // The imports decide what is published; this pins the outcome, so a new module reaching the page is a
  // visible change here as well as a row in the build's allow list. `drawings.js` is the one written
  // rather than compiled, `bin/drawings.ts`.
  assert.deepEqual(
    [...buildKeyReader().keys()],
    ['drawings.js', 'face.js', 'index.html', 'keys.js', 'link.js', 'models.js', 'page.js', 'presses.js', 'protocol.js', 'session.js'],
  );
});

test('every import in the published page names a file beside it', () => {
  for (const [name, content] of buildKeyReader()) {
    if (!name.endsWith('.js')) continue;
    for (const match of content.matchAll(/\bfrom\s+['"]([^'"]+)['"]/g)) {
      assert.match(match[1] as string, /^\.\/[a-z]+\.js$/, `${name} imports ${match[1]}`);
    }
  }
});

test('control: the drift check reports an edited file, a missing one and a stray one', () => {
  // Without this the first test could pass by comparing nothing.
  const built = buildKeyReader();
  const directory = mkdtempSync(join(tmpdir(), 'keyreader-drift-'));
  for (const [name, content] of built) writeFileSync(join(directory, name), content);
  assert.deepEqual(driftFrom(built, directory), []);
  writeFileSync(join(directory, 'link.js'), `${built.get('link.js')}\n// edited by hand\n`);
  writeFileSync(join(directory, 'extra.js'), '');
  const missing = new Map(built);
  missing.set('gone.js', '');
  assert.deepEqual(driftFrom(missing, directory).sort(), [
    'extra.js is not part of the page',
    'gone.js is missing',
    'link.js differs from its source',
  ]);
});
